var r=`0263-peka`;var a=`world-0263`;var i=`HR`;var o=`southern-europe`;var n=4;var s=197;var l={en:`Peka`,ua:`Пека`};var g={en:`A traditional Croatia dish made with lamb shoulder, potato, carrot, garlic. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Хорватія. Основні інгредієнти: лопатка ягняти, картопля, морква, часник. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var d=[{en:`Combine the seasoning ingredients and coat the main protein or vegetables. Rest covered in the refrigerator for about 40 minutes.`,ua:`Змішайте приправи й ретельно покрийте ними м’ясо або овочі. Маринуйте під накриттям у холодильнику приблизно 40 хвилин.`,t:[`marinating`],m:40,i:[[`lamb-shoulder`,700,`g`],[`potato`,480,`g`],[`carrot`,250,`g`],[`garlic`,5,`clove`],[`extra-virgin-olive-oil`,65,`ml`],[`rosemary`,2,`sprig`]]},{en:`Place meat and vegetables under a heavy covered roasting bell, or in a tightly lidded roasting pot, and roast at 190°C for about 2½ hours until tender.`,ua:`Накрийте м’ясо з овочами важкою кришкою для запікання або герметичною кришкою сотейника та готуйте при 190°C близько 2,5 години до м’якості.`,t:[`roasting`],m:155,i:[[`dry-white-wine`,180,`ml`],[`water`,180,`ml`]]},{en:`Uncover only for the final minutes to lightly brown the surface, then rest before serving the peka directly from the roasting dish.`,ua:`Відкрийте кришку лише на останні хвилини для легкого підрум’янення, дайте трохи постояти та подавайте пеку просто з форми.`,t:[`seasoning`,`garnishing`],m:2,i:[]}];var h={slug:r,id:a,country:`HR`,region:o,servings:4,minutes:197,title:l,text:g,steps:d};export{i as country,h as default,a as id,s as minutes,o as region,n as servings,r as slug,d as steps,g as text,l as title};